<template>
  <section class="list-page">
    <div class="page-head"><div><p>REPORT CONTROL CENTER</p><h2>运营日报进度</h2><span>按权限范围查看日报提交与月度目标完成情况。</span></div><a-button @click="load" :loading="loading">刷新数据</a-button></div>
    <div class="metric-grid"><article><small>已提交日报</small><strong>{{ rows.length }}</strong><span>当前筛选范围</span></article><article><small>覆盖运营人数</small><strong>{{ operatorCount }}</strong><span>去重统计</span></article><article><small>平均完成率</small><strong>{{ averageRate }}%</strong><span>仅统计已配置目标</span></article><article><small>目标未配置</small><strong>{{ missingTarget }}</strong><span>需管理端补充</span></article></div>
    <div class="filter-card"><a-range-picker v-model:value="dateRange" value-format="YYYY-MM-DD" :allow-clear="false"/><a-select v-model:value="operator" allow-clear placeholder="全部运营" style="min-width:180px"><a-select-option v-for="person in people" :key="person.id" :value="person.id">{{ person.real_name }}</a-select-option></a-select><a-button type="primary" @click="load">查询</a-button></div>
    <div class="table-card"><a-table :columns="columns" :data-source="rows" :loading="loading" row-key="id" :pagination="{pageSize:12}" @row="rowEvents"><template #bodyCell="{column,record}"><template v-if="column.key==='sales'">{{ money(record.cumulative_sales) }}</template><template v-else-if="column.key==='rate'"><span v-if="record.completion_rate!==null" class="rate">{{ record.completion_rate }}%</span><span v-else class="muted">目标未配置</span></template><template v-else-if="column.key==='status'"><a-tag color="green">已提交</a-tag></template></template><template #emptyText><a-empty description="当前范围暂无日报记录"/></template></a-table></div>
    <a-drawer v-model:open="drawerOpen" title="运营日报明细" width="520"><div v-if="selected" class="detail"><header><div><small>{{ selected.report_date }}</small><h3>{{ selected.operator_name }}</h3><p>{{ selected.department || '未配置部门' }}</p></div><span>{{ selected.completion_rate ?? 0 }}%</span></header><dl><div v-for="item in detailItems" :key="item.key"><dt>{{ item.label }}</dt><dd>{{ display(selected[item.key],item.type) }}</dd></div></dl></div></a-drawer>
  </section>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import dayjs from 'dayjs'; import { getDailyReports,getReportPeople } from '@/services/api'
const loading=ref(false),rows=ref([]),people=ref([]),operator=ref(),selected=ref(),drawerOpen=ref(false); const dateRange=ref([dayjs().startOf('month').format('YYYY-MM-DD'),dayjs().format('YYYY-MM-DD')]); const columns=[{title:'运营',dataIndex:'operator_name'},{title:'部门',dataIndex:'department'},{title:'填报日期',dataIndex:'report_date'},{title:'累计销售额',key:'sales'},{title:'完成率',key:'rate'},{title:'状态',key:'status'}]; const detailItems=[['cumulative_sales','累计销售额','money'],['listing_count','实际上架数量'],['optimization_count','产品优化数量'],['violation_triggered','触发违规 / 扣分','bool'],['infringement_triggered','链接侵权 / 禁售','bool'],['stocking_audit_rate','备货审核及时率','percent'],['reverse_product_count','产品反推数量'],['volatile_store_count','浮动 ≥20% 店铺数'],['all_issues_resolved','当天问题是否解决','bool']].map(([key,label,type])=>({key,label,type})); const operatorCount=computed(()=>new Set(rows.value.map(x=>x.operator_name)).size); const validRates=computed(()=>rows.value.filter(x=>x.completion_rate!==null)); const averageRate=computed(()=>validRates.value.length?(validRates.value.reduce((s,x)=>s+Number(x.completion_rate),0)/validRates.value.length).toFixed(1):'0.0'); const missingTarget=computed(()=>rows.value.filter(x=>x.completion_rate===null).length)
function money(v){return `¥ ${Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2})}`} function display(v,t){if(t==='money')return money(v);if(t==='bool')return v?'是':'否';if(t==='percent')return `${v}%`;return v??'-'} function rowEvents(record){return{onClick:()=>{selected.value=record;drawerOpen.value=true}}}
async function load(){loading.value=true;try{rows.value=await getDailyReports({start_date:dateRange.value[0],end_date:dateRange.value[1],operator_id:operator.value})}finally{loading.value=false}}
onMounted(async()=>{people.value=await getReportPeople();await load()})
</script>
<style scoped>
.list-page{max-width:1420px;margin:auto}.page-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:20px}.page-head p{margin:0 0 5px;color:#2f7df4;font-size:10px;font-weight:700;letter-spacing:.16em}.page-head h2{margin:0 0 6px;font-size:24px}.page-head span{color:#7e8ba1;font-size:13px}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin-bottom:16px}.metric-grid article{padding:18px;border:1px solid #dfe7f2;border-radius:10px;background:#fff}.metric-grid small,.metric-grid span{display:block;color:#8794a9}.metric-grid strong{display:block;margin:8px 0 4px;font-size:26px}.metric-grid span{font-size:10px}.filter-card,.table-card{border:1px solid #dfe7f2;border-radius:10px;background:#fff}.filter-card{display:flex;gap:10px;margin-bottom:14px;padding:14px}.table-card{padding:8px 12px}.table-card :deep(.ant-table-row){cursor:pointer}.rate{color:#1767df;font-weight:650}.muted{color:#9aa6b9}.detail header{display:flex;justify-content:space-between;padding:20px;border-radius:10px;color:#fff;background:linear-gradient(135deg,#2879ed,#70a9ff)}.detail h3{margin:5px 0;font-size:20px}.detail p,.detail small{margin:0;opacity:.8}.detail header>span{font-size:34px;font-weight:700}.detail dl{margin-top:16px}.detail dl div{display:flex;justify-content:space-between;padding:13px 4px;border-bottom:1px solid #e8edf4}.detail dt{color:#7e8ba1}.detail dd{margin:0;font-weight:600}@media(max-width:850px){.metric-grid{grid-template-columns:repeat(2,1fr)}.filter-card{flex-wrap:wrap}}@media(max-width:520px){.metric-grid{grid-template-columns:1fr}.page-head{align-items:start}}
</style>
